{
  "definition_simple": "宽广辽阔的天空。",
  "definition_standard": "辽阔无际的天空，多用于诗歌、散文等书面语境，带有宏大、高远的文学色彩。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "sentence": "雄鹰在长空中自由自在地飞翔。",
      "tier": "T1"
    },
    {
      "sentence": "一道闪电划破了寂静的长空。",
      "tier": "T2"
    },
    {
      "sentence": "清脆的哨声刺破长空，宣告着比赛的开始。",
      "tier": "T2"
    },
    {
      "sentence": "大雁排成整齐的队伍，飞越万里长空向南迁徙。",
      "tier": "T3"
    },
    {
      "sentence": "五彩斑斓的礼花直冲长空，瞬间点亮了整座城市的夜幕。",
      "tier": "T3"
    },
    {
      "sentence": "战机呼啸而过，在碧蓝如洗的长空中留下一道长长的白色航迹。",
      "tier": "T4"
    },
    {
      "sentence": "边塞秋风凛冽，数点归鸦振翅悲鸣，缓缓没入苍茫的暮色长空。",
      "tier": "T4"
    },
    {
      "sentence": "皓月当空，清冷幽微的银辉洒向无垠的长空与寂静的原野。",
      "tier": "T5"
    },
    {
      "sentence": "仰望深邃莫测的浩瀚长空，群星璀璨，令人顿生个体渺小与宇宙无穷之叹。",
      "tier": "T5"
    },
    {
      "sentence": "词人登高凭虚，俯仰于浩荡长空与滚滚江流之间，千古兴亡之感油然而生。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "长工",
      "explanation": "拼音为 chánggōng，与“长空 (chángkōng)”仅在后字声母存在送气音 [kʰ] 与不送气音 [k] 的细微区别，听辨极易混淆。"
    },
    {
      "word": "航空",
      "explanation": "拼音为 hángkōng，首字韵母与声调与“长”完全一致，仅声母从舌尖后音 ch 变为舌根音 h，快速语流中容易听错。"
    },
    {
      "word": "敞空",
      "explanation": "拼音为 chǎngkōng，与“长空”声母韵母完全相同，仅首字声调为第三声（上声）与第二声（阳平）之别。"
    }
  ],
  "primary_collocate": "划破",
  "collocation_distractors": [
    {
      "word": "撕烂",
      "explanation": "属于极口语化且针对纸张、布帛等柔软具体实物的破坏性动词，不能用于文学语境中的天幕意象。"
    },
    {
      "word": "打破",
      "explanation": "多用于硬质器具破碎或抽象的记录、平衡与僵局，与宏阔的空间意象不搭配。"
    },
    {
      "word": "割断",
      "explanation": "侧重于用刀具将条状物理连接或人际联系切断，无法搭配空灵无形的天空。"
    }
  ],
  "collocation_wrong_collocate": "切断",
  "cloze_distractors": [
    {
      "word": "高空",
      "explanation": "侧重物理高度与气象层面的客观空间（如“高空作业”），缺乏“长空”特有的文学美感与广袤诗意。"
    },
    {
      "word": "天气",
      "explanation": "词义完全不同，“天气”指气象状况，属于概念范畴错误，无法作为被动作穿透的空间实体。"
    },
    {
      "word": "蓝天",
      "explanation": "属于日常白话词汇，虽然语义相近，但在典雅古朴的诗意对仗句式中破坏了语体色彩。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "今天长空万里无云，温度正好，我们去菜市场买点新鲜蔬菜吧。",
      "explanation": "语体色彩严重失谐：“长空”为高雅书面语与文学词汇，不可用于日常琐碎生活的口语交际中。"
    },
    {
      "sentence": "工人们正在忙着用油漆把教室的长空粉刷成天蓝色。",
      "explanation": "语义范畴错误：“长空”特指广阔无垠的室外自然天幕，不能指代室内的天花板或屋顶。"
    },
    {
      "sentence": "这项工程难度极大，施工队经过了整整五年的长空才顺利完工。",
      "explanation": "词义理解错误：误将“长空”中的“长”理解为时间之长，将空间名词错用为表示时间跨度的量词或名词。"
    }
  ],
  "spot_incorrect": {
    "sentence": "那架客机在发生机械故障后迅速降低高度，最终平稳地降落在城市近郊的长空上。",
    "error_description": "“长空”指高远辽阔的天空，不能作为需要实体支撑的动作“降落”的着陆点宾语。",
    "corrected": "那架客机在发生机械故障后迅速降低高度，最终平稳地降落在城市近郊的机场跑道上。"
  },
